#include <vector>
#include <utility> // For std::pair

std::vector<int> interleave(const std::vector<int>& left, const std::vector<int>& right) {
    std::vector<int> result;
    size_t leftSize = left.size();
    size_t rightSize = right.size();

    // Use a loop to alternate between elements from both vectors
    while (leftSize > 0 && rightSize > 0) {
        if (leftSize > 0) {
            result.push_back(left.front());
            left.pop_front();
        }
        if (rightSize > 0) {
            result.push_back(right.front());
            right.pop_front();
        }
    }

    // Append any remaining elements from the left vector
    while (leftSize > 0) {
        result.push_back(left.front());
        left.pop_front();
    }

    // Append any remaining elements from the right vector
    while (rightSize > 0) {
        result.push_back(right.front());
        right.pop_front();
    }

    return result;
}
```

### Explanation:
- **Input Vectors**: The function takes two vectors, `left` and `right`, as input.
- **Result Vector**: A new vector `result` is initialized to store the interleaved elements.
- **Loop**: The function uses a `while` loop to iterate over both vectors until one of them is exhausted.
- **Alternating Elements**: Inside the loop, it checks if the current element from each vector is not empty. If so, it appends the element to the `result` vector and removes that element from the respective vector.
- **Remaining Elements**: After the loops finish, any remaining elements from the vectors are appended to the `result` vector.
- **Return**: The function returns the `result` vector containing the interleaved elements.

